import assert from 'node:assert/strict';
import test from 'node:test';
import { renderCatalog, catalogResponse } from '../src/next-catalog.mjs';

test('Next and React server APIs back the catalog boundary', async () => {
  const products = [{ id: 'lamp', name: 'Desk Lamp', priceCents: 4950 }];
  const html = renderCatalog(products);
  assert.match(html, /<section[^>]*aria-label=["']Products["']/);
  assert.match(html, /<article[^>]*data-product-id=["']lamp["']/);
  assert.match(html, /Desk Lamp/);
  assert.match(html, /\$49\.50/);
  const response = catalogResponse(products);
  assert.equal(response.constructor.name, 'NextResponse');
  assert.deepEqual(await response.json(), { products, count: 1 });
});

